import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import * as conv from "../runtime/conv.ts";
import * as ast from "../ast/index.ts";
import { buildNode, load, nodeAt } from "./testhelpers.ts";
import type { NodeSpec } from "./testhelpers.ts";
import type { Options } from "./renderer.ts";

// Vectors are generated by ts/tools/gen-render-vectors from Go's real render package (build tag javascript).
// The tests in this file need the whole render package, which imports the parse package; they are skipped while it cannot be imported.

interface LinkCase {
  linkBase?: string;
  linkPrefix?: string;
  dest?: string;
  relativePath?: string;
  prefixPath?: string;
  linkPath?: string;
  isRelativePath?: boolean;
  encodeLinkSpace?: string;
  prevent?: boolean;
  out?: string;
}
interface Plain {
  link: LinkCase[];
  subStr: [string, number, string][];
  noHighlight: [string, boolean][];
  appendTableCellAlignStyle: { align: number; in: string[][]; out: string[][] }[];
  setextHeadingMarkerOffset: [string, number][];
  isTabsParagraphMarker: [string, boolean][];
  mindmap: [string, string | null, string | null][];
}
type NodeInfo = Record<string, unknown>;
interface BaseMethodsTree {
  name: string;
  spec: NodeSpec;
  nodes: NodeInfo[];
}
interface BaseMethodsSrc {
  name: string;
  src: Record<string, unknown>[];
}
interface Trees {
  headings: { spec: NodeSpec; normalized: string[]; raw: string[]; headingText: string[]; renderHeadingText: string[]; ids: string[]; idsReverse: string[] }[];
  setext: { spec: NodeSpec; path: number[]; offset: number; escaped: string }[];
  tabsEscape: { spec: NodeSpec; path: number[]; tokens: string; withinTabsOnly: boolean; out: string | null }[];
  callout: { spec: NodeSpec; title: string; displayTitle: string; editableIcon: string; editableInfo: string }[];
  customBlock: { spec: NodeSpec; attrs: string[][] }[];
  mindmapNodes: { spec: NodeSpec; needRoot: boolean; texts: string[]; textNil: string }[];
  baseMethods: (BaseMethodsTree | BaseMethodsSrc)[];
}
const plain: Plain = JSON.parse(readFileSync(new URL("./testdata/render_vectors.json", import.meta.url), "utf8"));
const trees: Trees = JSON.parse(readFileSync(new URL("./testdata/render_tree_vectors.json", import.meta.url), "utf8"));
const loaded = await load();

function newRenderer(configure: (o: Options) => void, root: ast.Node | null = null) {
  const render = loaded.render!;
  const parse = loaded.parse!;
  const o = render.NewOptions();
  configure(o);
  const tree = new parse.Tree();
  tree.Root = root;
  return render.NewBaseRenderer(tree, o, parse.NewOptions());
}

test("link.go helpers match Go", { skip: loaded.skip }, () => {
  let count = 0;
  for (const v of plain.link) {
    if (undefined !== v.encodeLinkSpace) {
      const r = newRenderer((o) => {
        o.PreventEncodeLinkSpace = v.prevent!;
      });
      assert.equal(r.EncodeLinkSpace(v.encodeLinkSpace), v.out, "EncodeLinkSpace " + JSON.stringify(v));
      continue;
    }
    const r = newRenderer((o) => {
      o.LinkBase = v.linkBase!;
      o.LinkPrefix = v.linkPrefix!;
    });
    const dest = conv.BytesFromString(v.dest!);
    const what = JSON.stringify([v.linkBase, v.linkPrefix, v.dest]);
    assert.equal(conv.StringFromBytes(r.RelativePath(dest)), v.relativePath, "RelativePath " + what);
    assert.equal(conv.StringFromBytes(r.PrefixPath(dest)), v.prefixPath, "PrefixPath " + what);
    assert.equal(conv.StringFromBytes(r.LinkPath(dest)), v.linkPath, "LinkPath " + what);
    assert.equal(r.isRelativePath(dest), v.isRelativePath, "isRelativePath " + what);
    count++;
  }
  assert.ok(count > 400);
});

test("SubStr and NoHighlight match Go", { skip: loaded.skip }, () => {
  const render = loaded.render!;
  for (const [s, n, out] of plain.subStr) {
    assert.equal(render.SubStr(s, n), out, "SubStr " + JSON.stringify([s, n]));
  }
  for (const [s, out] of plain.noHighlight) {
    assert.equal(render.NoHighlight(s), out, "NoHighlight " + JSON.stringify(s));
  }
});

test("appendTableCellAlignStyle matches Go", { skip: loaded.skip }, () => {
  const render = loaded.render!;
  for (const v of plain.appendTableCellAlignStyle) {
    const n = new ast.Node(ast.NodeTableCell);
    n.TableCellAlign = v.align;
    const attrs = v.in.map((kv) => [...kv]);
    render.appendTableCellAlignStyle(n, attrs);
    assert.deepEqual(attrs, v.out, "align " + v.align + " in " + JSON.stringify(v.in));
  }
});

test("setext helpers match Go", { skip: loaded.skip }, () => {
  const render = loaded.render!;
  for (const [s, out] of plain.setextHeadingMarkerOffset) {
    assert.equal(render.setextHeadingMarkerOffset(conv.BytesFromString(s)), out, "input " + JSON.stringify(s));
  }
  for (const v of trees.setext) {
    const root = buildNode(v.spec);
    const n = nodeAt(root, v.path);
    assert.equal(render.setextHeadingMarkerOffsetInListParagraph(n), v.offset, "offset " + JSON.stringify(v.spec));
    const escaped = render.escapeSetextHeadingMarkersInListParagraph(n, conv.BytesFromString(conv.StringFromBytes(n.Tokens!)));
    assert.equal(conv.StringFromBytes(escaped), v.escaped, "escape " + JSON.stringify(v.spec));
  }
});

test("tabs.go helpers match Go", { skip: loaded.skip }, () => {
  const render = loaded.render!;
  for (const [s, out] of plain.isTabsParagraphMarker) {
    assert.equal(render.isTabsParagraphMarker(conv.BytesFromString(s)), out, "input " + JSON.stringify(s));
  }
  for (const v of trees.tabsEscape) {
    const root = buildNode(v.spec);
    const n = nodeAt(root, v.path);
    const out = conv.StringFromBytes(render.escapeTabsParagraphMarkers(n, conv.BytesFromString(v.tokens), v.withinTabsOnly));
    assert.equal(out, v.out, "input " + JSON.stringify(v));
  }
});

test("callout.go helpers match Go", { skip: loaded.skip }, () => {
  const render = loaded.render!;
  assert.ok(trees.callout.length >= 100);
  for (const v of trees.callout) {
    const n = buildNode(v.spec);
    const what = JSON.stringify(v.spec.props);
    assert.equal(render.calloutTitle(n), v.title, "calloutTitle " + what);
    assert.equal(render.calloutDisplayTitle(n), v.displayTitle, "calloutDisplayTitle " + what);
    assert.equal(render.calloutEditableIcon(n), v.editableIcon, "calloutEditableIcon " + what);
    assert.equal(render.calloutEditableInfo(n), v.editableInfo, "calloutEditableInfo " + what);
  }
});

test("custom_block_renderer.go helpers match Go", { skip: loaded.skip }, () => {
  const render = loaded.render!;
  for (const v of trees.customBlock) {
    assert.deepEqual(render.customBlockAttrs(buildNode(v.spec)), v.attrs, JSON.stringify(v.spec));
  }
});

test("heading id and text helpers match Go", { skip: loaded.skip }, () => {
  const render = loaded.render!;
  const headingsOf = (root: ast.Node): ast.Node[] => root.ChildrenByType(ast.NodeHeading);
  for (const v of trees.headings) {
    const what = JSON.stringify(v.spec);
    const root = buildNode(v.spec);
    const hs = headingsOf(root);
    assert.equal(hs.length, v.normalized.length);
    assert.deepEqual(hs.map((h) => render.normalizeHeadingID(h)), v.normalized, "normalizeHeadingID " + what);
    assert.deepEqual(hs.map((h) => render.HeadingIDRaw(h)), v.raw, "HeadingIDRaw " + what);
    assert.deepEqual(hs.map((h) => render.headingText(h)), v.headingText, "headingText " + what);
    assert.deepEqual(hs.map((h) => render.RenderHeadingText(h)), v.renderHeadingText, "RenderHeadingText " + what);
    assert.deepEqual(hs.map((h) => render.HeadingID(h)), v.ids, "HeadingID " + what);
    const root2 = buildNode(v.spec);
    const hs2 = headingsOf(root2);
    const rev: string[] = [];
    for (let i = hs2.length - 1; 0 <= i; i--) {
      rev.push(render.HeadingID(hs2[i]));
    }
    assert.deepEqual(rev, v.idsReverse, "HeadingID reverse " + what);
  }
});

test("mindmap.go helpers on hand-built nodes match Go", { skip: loaded.skip }, () => {
  const render = loaded.render!;
  for (const v of trees.mindmapNodes) {
    const root = buildNode(v.spec);
    assert.equal(render.needRoot(root), v.needRoot, JSON.stringify(v.spec));
    const texts = root.ChildrenByType(ast.NodeListItem).map((li) => render.text(li.FirstChild));
    assert.deepEqual(texts, v.texts ?? [], JSON.stringify(v.spec)); // a Go nil slice is null in the JSON
    assert.equal(render.text(null), v.textNil);
  }
});

test("EChartsMindmap and EChartsMindmapStr match Go", { skip: loaded.skip }, () => {
  const render = loaded.render!;
  for (const [s, str, bytes] of plain.mindmap) {
    if (null === str) {
      assert.throws(() => render.EChartsMindmapStr(s), "input " + JSON.stringify(s));
      continue;
    }
    assert.equal(render.EChartsMindmapStr(s), str, "EChartsMindmapStr " + JSON.stringify(s));
    assert.equal(conv.StringFromBytes(render.EChartsMindmap(conv.BytesFromString(s))), bytes, "EChartsMindmap " + JSON.stringify(s));
  }
});

test("BaseRenderer tree helpers match Go", { skip: loaded.skip }, () => {
  for (const c of trees.baseMethods) {
    if ("src" in c) {
      for (const v of c.src) {
        const input = conv.BytesFromString(v["in"] as string);
        const r0 = newRenderer(() => {});
        if ("PANIC" === v["tagSrc"]) {
          assert.throws(() => r0.tagSrc(input), "tagSrc " + JSON.stringify(v));
        } else {
          const got = r0.tagSrc(input);
          assert.equal(null === got ? null : conv.StringFromBytes(got), v["tagSrc"], "tagSrc " + JSON.stringify(v));
        }
        for (const base of ["", "http://b/"]) {
          for (const prefix of ["", "/pre"]) {
            const r = newRenderer((o) => {
              o.LinkBase = base;
              o.LinkPrefix = prefix;
            });
            assert.equal(conv.StringFromBytes(r.tagSrcPath(input)), v["tagSrcPath|" + base + "|" + prefix], "tagSrcPath " + JSON.stringify([v["in"], base, prefix]));
          }
        }
      }
      continue;
    }
    const root = buildNode(c.spec);
    const r = newRenderer(() => {}, root);
    const nodes: ast.Node[] = [];
    ast.Walk(root, (n, entering) => {
      if (entering) {
        nodes.push(n);
      }
      return ast.WalkContinue;
    });
    assert.equal(nodes.length, c.nodes.length, c.name);
    nodes.forEach((n, i) => {
      const e = c.nodes[i];
      const what = c.name + " node " + i + " " + ast.NodeTypeString(n.Type);
      assert.equal(r.Text(n), e["text"], "Text " + what);
      assert.equal(r.NodeAttrsStr(n), e["attrsStr"], "NodeAttrsStr " + what);
      assert.deepEqual(r.NodeAttrs(n), e["attrs"] ?? [], "NodeAttrs " + what);
      assert.equal(r.ParagraphContainImgOnly(n), e["paragraphContainImgOnly"], "ParagraphContainImgOnly " + what);
      assert.equal(r.needUseHTMLTable(n), e["needUseHTMLTable"], "needUseHTMLTable " + what);
      assert.equal(r.isLastNode(root, n), e["isLastNode"], "isLastNode " + what);
      if (ast.NodeHeading === n.Type) {
        assert.equal(r.setextHeadingLen(n), e["setextHeadingLen"], "setextHeadingLen " + what);
      }
      assert.equal(n.IALAttr("id"), e["ialID"], "IALAttr id " + what);
    });
  }
});
